(()=>{
'use strict';
const chat=document.querySelector('.chat'),events=document.querySelector('#events');
if(!chat||!events)return;
const style=document.createElement('style');
style.textContent="#chibiRoom .sprite{position:absolute;inset:0;background-image:url(data:image/webp;base64,);background-size:400% 200%;background-repeat:no-repeat;background-position:0 0}\n#chibiTools{display:flex;gap:8px;flex-wrap:wrap;padding:8px 12px;background:#fff;border-bottom:1px solid #d7e0eb;flex:none}\n#chibiTools button,#chibiTools a{font:inherit;font-size:12px;padding:6px 9px;border:1px solid #b9c9dd;border-radius:8px;background:#f4f8ff;color:#234366;text-decoration:none;cursor:pointer}\n#chibiRoom{flex:none;background:#edf4fc;padding:10px;max-height:220px;overflow:auto;border-bottom:1px solid #cad8e8}\n#chibiRoom.large{max-height:none;flex:1;min-height:0}\n#chibiRoom[hidden]{display:none}\n#chibiRoom .pair{display:flex;justify-content:center;gap:18px}\n#chibiRoom .person{width:140px;max-width:42%}\n#chibiRoom.large .person{width:230px}\n#chibiRoom .portrait{position:relative;aspect-ratio:384/512;background:#fff;overflow:hidden;border-radius:12px}\n#chibiRoom .sprite{inset:0}\n#chibiRoom .junior{background-position:0 100%}\n#chibiRoom .say{padding:10px;border-radius:10px;background:#fff;font-size:14px;line-height:1.6;min-height:64px;margin:8px 0}\n#chibiRoom .status{font-size:13px;margin:0 0 8px;color:#315476}\n#chibiRoom:not(.large) .pair{justify-content:flex-start;align-items:center}\n#chibiRoom:not(.large) .person{display:flex;align-items:center;width:48%;max-width:none;gap:8px}\n#chibiRoom:not(.large) .portrait{width:56px;flex:none}\n#chibiRoom:not(.large) .say{font-size:12px;min-height:0}\n@media(max-width:760px){#chibiRoom{max-height:160px}#chibiRoom:not(.large) .portrait{width:38px}#chibiRoom.large .person{width:150px}#chibiTools{gap:4px}#chibiRoom .say{font-size:13px}}\n";
style.textContent+="\n/* Small desktop companions; room expansion must not enlarge the characters. */\n#chibiRoom .pair{align-items:flex-end;justify-content:center;gap:24px;flex-wrap:wrap}\n#chibiRoom .person,#chibiRoom.large .person{width:180px;max-width:45%;display:flex;flex-direction:column;align-items:center}\n#chibiRoom .portrait,#chibiRoom.large .portrait{width:54px;height:72px;aspect-ratio:auto;flex:none;border-radius:0}\n#chibiRoom .say{width:100%;font-size:14px;line-height:1.6;min-height:0}\n#chibiRoom.large .pair{min-height:210px}\n#chibiRoom:not(.large) .person{flex-direction:row;width:48%;max-width:none}\n#chibiRoom:not(.large) .portrait{width:42px;height:56px}\n@media(max-width:760px){#chibiRoom .portrait,#chibiRoom.large .portrait{width:42px;height:56px}#chibiRoom .say{font-size:13px}#chibiRoom .pair{gap:12px}#chibiRoom:not(.large) .portrait{width:36px;height:48px}}\n";
style.textContent+="\n#chibiRoom .pair{position:relative;display:block!important;height:180px;min-height:180px;overflow:hidden}\n#chibiRoom.large .pair{height:clamp(240px,42vh,480px)}\n#chibiRoom .person,#chibiRoom.large .person,#chibiRoom:not(.large) .person{position:absolute;bottom:8px;left:0;display:block;width:54px;max-width:none;will-change:transform}\n#chibiRoom .say,#chibiRoom:not(.large) .say{position:absolute;bottom:78px;left:var(--bubble-left,0px);width:190px;max-width:calc(100vw - 60px);margin:0;padding:9px;font-size:13px;box-shadow:0 3px 12px #19314d15}\n#chibiRoom .say:empty{display:none}\n#chibiRoom .portrait,#chibiRoom.large .portrait,#chibiRoom:not(.large) .portrait{width:54px;height:72px}\n#chibiRoom .stationbar{display:flex;justify-content:space-between;gap:10px;color:#536b86;font-size:12px;padding:6px 3px;border-bottom:1px solid #bfd0e3}\n#chibiRoom .action-label{text-align:center;font-size:11px;white-space:nowrap;color:#426080}\n@media(max-width:760px){#chibiRoom .portrait,#chibiRoom.large .portrait,#chibiRoom:not(.large) .portrait{width:42px;height:56px}#chibiRoom .person{width:42px!important}#chibiRoom .say{bottom:65px;width:160px}#chibiRoom:not(.large){max-height:240px}}\n";
document.head.append(style);
const tools=document.createElement('div');tools.id='chibiTools';
tools.innerHTML='<b style="font-size:12px;align-self:center">ちびキャラ実装テスト</b><button type="button" id="chibiToggle">演出OFF</button><button type="button" id="chibiWide">編集室を広く表示</button><button type="button" id="chibiPause">一時停止</button><a href="./">通常の編集部へ</a>';
const room=document.createElement('section');room.id='chibiRoom';room.setAttribute('aria-label','先輩と後輩の編集室');
room.innerHTML='<p class="status"></p><div class="pair"><div class="person"><div class="portrait"><div class="sprite"></div></div><p class="say" data-senior></p></div><div class="person"><div class="portrait"><div class="sprite junior"></div></div><p class="say" data-junior></p></div></div>';
chat.insertBefore(tools,events);chat.insertBefore(room,events);
const stations=document.createElement('div');stations.className='stationbar';stations.innerHTML='<span>休憩スペース</span><span>資料・作業スペース</span>';room.querySelector('.pair').before(stations);
const people=[...room.querySelectorAll('.person')];
people.forEach(el=>{const label=document.createElement('div');label.className='action-label';el.append(label)});

const terminal=new Set(['COMPLETED','CANCELLED','CLOSED','REJECTED','PUBLISHED','MERGED','DONE']);
const dialog={
idle:['次の仕事まで、ひと休みだね。','メモを整理しながら待っています。'],
work:['いまの工程を進めているところだね。','会話の記録は上の案件から確認できます。'],
research:['調査の工程だね。根拠を確かめよう。','分からないところも、メモに残します。'],
build:['制作の工程だね。読みやすさも大切に。','見出しの順番も気になりますね。'],
human:['ここは管理者の確認待ちだね。','返事が来るまでは待ちましょう。'],
error:['いまは状態の確認が必要だね。','進んだことにせず、確認しましょう。'],
history:['過去の案件を確認しているところだね。','本文を読めるよう、端で待っています。']
};
let enabled=true,wide=false,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
let base=0,started=performance.now(),lastMode='';
try{enabled=localStorage.getItem('chibi-room-enabled')!=='false'}catch{}
function sync(){
const locked=document.querySelector('#app').classList.contains('appLocked');
const offline=document.querySelector('#conn').classList.contains('off');
const home=events.dataset.job==='__home__';
let mode='idle',all=[];
try{all=groupedJobs()}catch{mode='error'}
const live=all.filter(g=>!terminal.has(String(g.last?.state||'').toUpperCase()));
const selected=all.find(g=>g.id===events.dataset.job);
const current=selected&&!terminal.has(String(selected.last?.state||'').toUpperCase())?selected:live[0];
if(offline)mode='error';
else if(!home&&selected&&terminal.has(String(selected.last?.state||'').toUpperCase()))mode='history';
else if(current){
const state=String(current.last?.state||'').toUpperCase(),age=Date.now()-Date.parse(current.last?.created_at);
mode=['HUMAN_GATE','NEEDS_HUMAN'].includes(state)?'human':['FAILED','ESCALATED','ERROR'].includes(state)||!Number.isFinite(age)||age>180000?'error':state==='RESEARCHING'?'research':state==='BUILDING'?'build':'work';
}
room.hidden=locked||!enabled;const large=enabled&&!locked&&!offline&&(wide||home);room.classList.toggle('large',large);
events.hidden=large;document.querySelector('.roomHead').hidden=large;
document.querySelector('#chibiToggle').textContent=enabled?'演出OFF':'演出ON';
document.querySelector('#chibiWide').textContent=wide?'チャット表示へ':'編集室を広く表示';
document.querySelector('#chibiPause').textContent=paused?'再生':'一時停止';
room.querySelector('.status').textContent=({idle:'待機中',history:'履歴閲覧中',work:'案件対応中',research:'調査中',build:'制作中',human:'管理者確認待ち',error:'状態の確認が必要です'})[mode]+' · キャラクター演出';
if(mode!==lastMode){lastMode=mode;modeSince=clock();speech=null;room.querySelector('[data-senior]').textContent='';room.querySelector('[data-junior]').textContent='';}
}
document.querySelector('#chibiToggle').onclick=()=>{enabled=!enabled;try{localStorage.setItem('chibi-room-enabled',String(enabled))}catch{}sync()};
document.querySelector('#chibiWide').onclick=()=>{wide=!wide;sync()};
document.querySelector('#chibiPause').onclick=()=>{base+=paused?0:performance.now()-started;started=performance.now();paused=!paused;sync()};
document.querySelector('#jobs').addEventListener('click',()=>{wide=false;setTimeout(sync,0)});

function clock(){return (base+(paused?0:performance.now()-started))/1000}
let modeSince=0,speech=null,lastSlot=-1;
const banter=[
['休憩の準備は万全だね。','メモ帳まで持ってきました！'],
['その付箋、ずいぶん増えたね。','大事なところに貼ったら、全部大事でした。'],
['今日は静かな時間も大切にしよう。','了解です。静かに張り切ります。'],
['机の上、きれいになったね。','引き出しの中は、次の課題です。'],
['次の仕事まで、少し肩の力を抜こう。','はい。ヘルメットはそのままで。'],
['メモを見返しているの？','未来の自分に読める字か確認しています。'],
['資料は元の場所に戻しておこう。','次に探す自分のためですね。'],
['ひと息つくのも、いいものだね。','休憩の段取りは得意になりました。'],
['そのノート、新しい？','最初のページだけ、いつも丁寧になります。'],
['今日の振り返りは何かな。','探し物をする前に、手元を見ることです。'],
['整理のコツ、見つかった？','「その他」を増やしすぎないことですね。'],
['次も一つずつ進めよう。','一つずつなら、メモも追いつけます。']
];
let history={};try{const h=JSON.parse(localStorage.getItem('chibi-dialog-history-v1')||'{}');if(h&&typeof h==='object'&&!Array.isArray(h))history=h}catch{}
function chooseSpeech(){
const now=Date.now(),items=lastMode==='idle'?banter:[dialog[lastMode]||dialog.error];
const candidates=items.map((text,i)=>({text,id:lastMode+':'+i})).filter(x=>!Number.isFinite(history[x.id])||now-history[x.id]>=7200000);
if(!candidates.length)return null;
const pick=candidates[Math.floor(Math.random()*candidates.length)];history[pick.id]=now;
Object.keys(history).forEach(k=>{if(now-history[k]>7200000)delete history[k]});
try{localStorage.setItem('chibi-dialog-history-v1',JSON.stringify(history))}catch{}
return {text:pick.text,at:clock()};
}
const positions=[.14,.68],smooth=x=>x*x*(3-2*x);
function animate(){
if(!room.isConnected)return;
const t=clock(),local=t-modeSince;
if(enabled&&!room.hidden){
const slot=Math.floor(t/55);
if(slot!==lastSlot){lastSlot=slot;speech=chooseSpeech()}
const speechAge=speech?t-speech.at:999;
const stage=Math.floor(local/12)%6,part=(local%12)/12;
const active=['work','research','build'].includes(lastMode);
const hold=['error','human','history'].includes(lastMode);
let targets=hold?[.3,.65]:active?[.62,.8]:stage%2?[.36,.62]:[.12,.77];
const width=room.querySelector('.pair').clientWidth;
people.forEach((el,i)=>{
const aim=targets[i];if(!paused){const delta=aim-positions[i];positions[i]+=Math.sign(delta)*Math.min(Math.abs(delta),.0025)}
const x=Math.max(0,Math.min(width-54,positions[i]*(width-54)));
el.style.transform='translateX('+x+'px)';
el.querySelector('.portrait').style.transform='scaleY('+(1+Math.sin(t*1.5+i)*.0015)+')';
const saying=speech&&(i===0?speechAge<8:speechAge>=8&&speechAge<16);
el.querySelector('.say').textContent=saying?speech.text[i]:'';
el.style.setProperty('--bubble-left',Math.min(0,Math.max(-x,width-x-190))+'px');
const moving=Math.abs(aim-positions[i])>.015;
el.querySelector('.action-label').textContent=moving?'移動中':lastMode==='research'?'資料を確認':lastMode==='build'?'原稿を整理':lastMode==='work'?'作業中':lastMode==='human'?'確認待ち':lastMode==='error'?'状況を確認':lastMode==='history'?'静かに待機':stage%2?'ひと休み':'散歩';
});
}
requestAnimationFrame(animate);
}
sync();setInterval(sync,1000);requestAnimationFrame(animate);
})();